// Inicialização do Workflow Unificado
const timestamp = new Date().toISOString();
const sessionId = 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);

return [{
  json: {
    sessionId: sessionId,
    timestamp: timestamp,
    orchestrator: {
      name: 'Workflow Unificado CredGestor',
      version: '2.0',
      role: 'Coordenação completa: monitoramento, troubleshooting e resolução'
    },
    status: 'initializing',
    agents: {
      containers: { status: 'pending', called: false },
      database: { status: 'pending', called: false },
      development: { status: 'pending', called: false }
    }
  }
}];

// Análise Inicial dos Dados Coletados
const initData = $('Inicializar').item.json;
const healthApi = $('Health Check API').item.json;
const metrics = $('Verificar Métricas').item.json;
const frontend = $('Health Check Frontend').item.json;
const dbConnections = $('Verificar Conexões DB').item.json[0] || {};

const analysis = {
  api: {
    status: healthApi.statusCode === 200 ? 'healthy' : 'unhealthy',
    statusCode: healthApi.statusCode,
    response: healthApi.body || {}
  },
  metrics: {
    status: metrics.statusCode === 200 ? 'available' : 'unavailable',
    hasData: metrics.statusCode === 200
  },
  frontend: {
    status: frontend.statusCode === 200 ? 'healthy' : 'unhealthy',
    statusCode: frontend.statusCode
  },
  database: {
    totalConnections: parseInt(dbConnections.total_connections || 0),
    activeConnections: parseInt(dbConnections.active_connections || 0),
    idleConnections: parseInt(dbConnections.idle_connections || 0),
    status: 'healthy'
  }
};

// Detectar problemas iniciais
const issues = [];

if (analysis.api.status === 'unhealthy' || analysis.metrics.status === 'unavailable') {
  issues.push({
    type: 'infrastructure',
    severity: 'critical',
    component: 'backend',
    message: 'API ou métricas com problemas'
  });
}

if (analysis.database.totalConnections > 50 || analysis.database.activeConnections > 30) {
  issues.push({
    type: 'database',
    severity: 'warning',
    component: 'database',
    message: 'Muitas conexões ativas: ' + analysis.database.activeConnections
  });
}

if (analysis.frontend.status === 'unhealthy') {
  issues.push({
    type: 'frontend',
    severity: 'critical',
    component: 'frontend',
    message: 'Frontend retornou status ' + analysis.frontend.statusCode
  });
}

return [{
  json: {
    ...initData,
    analysis: analysis,
    issues: issues,
    readyForClaude: true
  }
}];

