// Processar decisão do Claude.ai
const analysisData = $('Análise Inicial').item.json;
const llmResponse = $input.item.json;

// Extrair texto da resposta
let decisionText = '';
let responseBody = llmResponse.body || llmResponse;
if (typeof responseBody === 'string') {
  try {
    responseBody = JSON.parse(responseBody);
  } catch (e) {
    responseBody = { content: [{ type: 'text', text: responseBody }] };
  }
}

if (responseBody.content && Array.isArray(responseBody.content)) {
  const textContent = responseBody.content.find(c => c.type === 'text');
  decisionText = textContent ? textContent.text : JSON.stringify(responseBody.content);
} else {
  decisionText = JSON.stringify(responseBody);
}

// Parsear JSON da resposta
let agentsToCall = [];
let reasoning = 'Análise automática';
let priority = 'medium';

try {
  const jsonMatch = decisionText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    agentsToCall = parsed.agentsToCall || [];
    reasoning = parsed.reasoning || reasoning;
    priority = parsed.priority || priority;
  }
} catch (e) {
  // Fallback: decidir baseado em problemas detectados
  if (analysisData.issues.some(i => i.type === 'infrastructure')) agentsToCall.push('containers');
  if (analysisData.issues.some(i => i.type === 'database')) agentsToCall.push('database');
  if (analysisData.issues.some(i => i.type === 'frontend')) agentsToCall.push('development');
}

// Remover duplicatas
const uniqueAgents = [...new Set(agentsToCall)];

return [{
  json: {
    ...analysisData,
    agentsToCall: uniqueAgents,
    decision: {
      timestamp: new Date().toISOString(),
      reasoning: reasoning,
      priority: priority,
      claudeDecision: true
    },
    status: analysisData.issues.length > 0 ? 'issues_detected' : 'healthy'
  }
}];

// Preparar chamadas para agentes especializados
// Cada agente fará troubleshooting E resolução
const data = $input.item.json;
const agentsToCall = data.agentsToCall || [];

const agentConfig = {
  containers: {
    name: 'Agente Especialista em Containers',
    endpoint: $env.WORKFLOW_AGENTE_CONTAINERS_URL || 'http://localhost:5678/webhook/agente-containers',
    specialization: ['Docker Swarm', 'Containers', 'Serviços', 'Logs', 'Recursos']
  },
  database: {
    name: 'Agente Especialista em Banco de Dados',
    endpoint: $env.WORKFLOW_AGENTE_DB_URL || 'http://localhost:5678/webhook/agente-database',
    specialization: ['PostgreSQL', 'Supabase', 'Queries', 'Performance']
  },
  development: {
    name: 'Agente Especialista em Desenvolvimento',
    endpoint: $env.WORKFLOW_AGENTE_DEV_URL || 'http://localhost:5678/webhook/agente-dev',
    specialization: ['React', 'FastAPI', 'Código', 'Integração']
  }
};

const agentCalls = agentsToCall.map(agentType => {
  const config = agentConfig[agentType];
  if (!config) return null;

  return {
    agentType: agentType,
    agentName: config.name,
    endpoint: config.endpoint,
    specialization: config.specialization,
    payload: {
      sessionId: data.sessionId,
      timestamp: data.timestamp,
      orchestratorDecision: data.decision,
      issues: data.issues.filter(i => 
        (agentType === 'containers' && (i.type === 'infrastructure' || i.component === 'backend')) ||
        (agentType === 'database' && (i.type === 'database' || i.component === 'database')) ||
        (agentType === 'development' && (i.type === 'frontend' || i.component === 'frontend'))
      ),
      context: {
        api: data.analysis.api,
        metrics: data.analysis.metrics,
        frontend: data.analysis.frontend,
        database: data.analysis.database
      },
      mode: 'troubleshooting_and_resolution' // Modo unificado
    }
  };
}).filter(call => call !== null);

return agentCalls.map(call => ({ json: call }));

// Processar resposta dos agentes especializados
const agentCall = $('Processar Chamadas').item.json;
const agentResponse = $input.item.json;

// Processar resposta
let response = {};
if (agentResponse.body) {
  response = typeof agentResponse.body === 'string' 
    ? JSON.parse(agentResponse.body) 
    : agentResponse.body;
} else {
  response = agentResponse;
}

return [{
  json: {
    agentType: agentCall.agentType,
    agentName: agentCall.agentName,
    sessionId: agentCall.payload.sessionId,
    response: response,
    status: agentResponse.statusCode === 200 ? 'success' : 'error',
    timestamp: new Date().toISOString()
  }
}];

// Consolidar resultados de todos os agentes
const orchestratorData = $('Processar Decisão').item.json;
const agentResponses = $input.all();

const consolidatedAnalysis = {
  sessionId: orchestratorData.sessionId,
  timestamp: orchestratorData.timestamp,
  orchestrator: orchestratorData.orchestrator,
  issues: orchestratorData.issues,
  agentAnalyses: agentResponses.map(r => r.json),
  summary: {
    totalAgentsCalled: agentResponses.length,
    agentsWithIssues: agentResponses.filter(r => r.json.response && r.json.response.hasIssues).length,
    criticalIssues: orchestratorData.issues.filter(i => i.severity === 'critical').length,
    totalActions: agentResponses.reduce((sum, r) => {
      const troubleshooting = r.json.response?.troubleshooting || {};
      const resolution = r.json.response?.resolution || {};
      const troubleshootingActions = troubleshooting.actionPlan?.length || 0;
      const resolutionActions = resolution.executionPlan?.length || 0;
      return sum + troubleshootingActions + resolutionActions;
    }, 0)
  },
  troubleshooting: agentResponses.reduce((plan, r) => {
    const troubleshooting = r.json.response?.troubleshooting || {};
    const actions = troubleshooting.actionPlan || [];
    return plan.concat(actions.map(a => ({
      ...a,
      agent: r.json.agentType,
      agentName: r.json.agentName
    })));
  }, []),
  resolution: agentResponses.reduce((plan, r) => {
    const resolution = r.json.response?.resolution || {};
    const actions = resolution.executionPlan || [];
    return plan.concat(actions.map(a => ({
      ...a,
      agent: r.json.agentType,
      agentName: r.json.agentName
    })));
  }, []),
  requiresApproval: agentResponses.some(r => {
    const troubleshooting = r.json.response?.troubleshooting || {};
    const resolution = r.json.response?.resolution || {};
    return troubleshooting.requiresApproval === true || resolution.requiresApproval === true;
  })
};

return [{
  json: consolidatedAnalysis
}];

// Formatar notificação consolidada
const consolidated = $('Consolidar Resultados').item.json;
const savedReport = $('Salvar Relatório').item.json[0];

const severity = consolidated.issues.some(i => i.severity === 'critical') ? 'critical' : 'medium';
const severityEmoji = {
  'critical': '🔴',
  'high': '🟠',
  'medium': '🟡',
  'low': '🟢'
}[severity] || '⚪';

let message = severityEmoji + ' *ALERTA MULTI-AGENTE: Problema Detectado e Resolvido no CredGestor*\n\n';
message += '*Workflow Unificado* coordenou ' + consolidated.summary.totalAgentsCalled + ' agente(s) especializado(s)\n';
message += '*Severidade:* ' + severity.toUpperCase() + '\n';
message += '*Data/Hora:* ' + new Date(consolidated.timestamp).toLocaleString('pt-BR') + '\n\n';

message += '*📋 PROBLEMAS DETECTADOS:*\n';
for (const issue of consolidated.issues) {
  message += '• ' + issue.type + ': ' + issue.message + ' (' + issue.severity + ')\n';
}

message += '\n*🔍 TROUBLESHOOTING REALIZADO:*\n';
for (const agentAnalysis of consolidated.agentAnalyses) {
  const troubleshooting = agentAnalysis.response?.troubleshooting || {};
  if (troubleshooting.diagnosis) {
    const summary = troubleshooting.diagnosis.summary || 'Análise concluída';
    message += '\n*' + agentAnalysis.agentName + ':*\n';
    message += summary.substring(0, 200) + '...\n';
  }
}

message += '\n*🔧 PLANO DE RESOLUÇÃO GERADO:*\n';
for (let i = 0; i < Math.min(consolidated.resolution.length, 5); i++) {
  const action = consolidated.resolution[i];
  message += (i + 1) + '. [' + action.agent + '] ' + action.description + '\n';
}
if (consolidated.resolution.length > 5) {
  message += '... e mais ' + (consolidated.resolution.length - 5) + ' ações\n';
}

message += '\n*⚠️ AÇÕES REQUEREM APROVAÇÃO*\n';
message += 'ID do Relatório: ' + (savedReport.id || 'N/A') + '\n\n';

message += '*Para aprovar e executar:*\n';
message += 'Responda: APROVAR ' + (savedReport.id || 'REPORT_ID') + '\n\n';
message += '*Para rejeitar:*\n';
message += 'Responda: REJEITAR ' + (savedReport.id || 'REPORT_ID') + '\n';

return [{
  json: {
    message: message,
    reportId: savedReport.id,
    consolidated: consolidated,
    channel: '#credgestor-alerts',
    thread_ts: null
  }
}];

// Resumo final
const consolidated = $('Consolidar Resultados').item.json;
const savedReport = $('Salvar Relatório').item.json[0];

return [{
  json: {
    executionTime: new Date().toISOString(),
    sessionId: consolidated.sessionId,
    reportId: savedReport.id,
    orchestrator: consolidated.orchestrator,
    agentsCalled: consolidated.summary.totalAgentsCalled,
    issuesFound: consolidated.issues.length,
    troubleshootingActions: consolidated.troubleshooting.length,
    resolutionActions: consolidated.resolution.length,
    requiresApproval: consolidated.requiresApproval,
    status: 'completed'
  }
}];
